#include <stdio.h>

int power(int base, int exponent) {
    int result = 1;
    for (int i = 0; i < exponent; i++) {
        result *= base;
    }
    return result;
}

int main() {
    printf("2^10 = %d\n", power(2, 10));
    printf("5^3 = %d\n", power(5, 3));
    printf("7^0 = %d\n", power(7, 0));
    return 0;
}
